export type ScriptLevel = "beginner" | "intermediate" | "advanced";
export type ScriptType =
  | "closed"
  | "not_interested"
  | "callback"
  | "price_objection"
  | "existing_provider"
  | "send_email"
  | "multi_objection"
  | "decision_maker";

export interface ScriptTurn {
  id: string;
  role: "customer" | "agent";
  text: string;
  note?: string;
}

export interface MockScript {
  id: string;
  title: string;
  level: ScriptLevel;
  type: ScriptType;
  scenario: string;
  outcome: string;
  turns: ScriptTurn[];
}

